import bisect

def solve(nums):
    """Return length of longest strictly increasing subsequence of nums.
    Uses patience sorting with binary search, O(n log n).
    """
    if not nums:
        return 0
    # tails[i] = smallest possible tail value of an increasing subsequence of length i+1
    tails = []
    for x in nums:
        # find index of smallest element >= x (since strictly increasing, we need >? Actually we replace first >= x)
        # For strict increase, we use bisect_left on tails with x
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

