def solve(meetings):
    """Return the maximum number of non‑overlapping meetings.
    meetings: iterable of [start, end] pairs. Handles malformed entries gracefully.
    A meeting may start exactly when another ends.
    """
    # Guard against None or non‑iterable input
    if not meetings:
        return 0
    normalized = []
    for m in meetings:
        # Expect a sequence of at least two items
        try:
            start, end = m[0], m[1]
        except Exception:
            continue
        # Convert to numbers if possible
        try:
            start = int(start)
            end = int(end)
        except Exception:
            continue
        # Ensure start <= end
        if start > end:
            start, end = end, start
        normalized.append((start, end))
    if not normalized:
        return 0
    # Sort by end time, then by start for deterministic tie‑breaker
    normalized.sort(key=lambda x: (x[1], x[0]))
    count = 0
    current_end = -10**18  # sufficiently small
    for start, end in normalized:
        if start >= current_end:
            count += 1
            current_end = end
    return count

