def solve(s):
    """Return the length of the longest substring of s with no repeated characters.

    Classic sliding window: expand the right edge, and move the left edge
    forward while a duplicate is inside the window.
    """
    if not s:
        return 0
    last_seen = {}
    start = 0
    best = 0
    for i, ch in enumerate(s):
        if ch in last_seen and last_seen[ch] >= start:
            start = last_seen[ch] + 1
        last_seen[ch] = i
        window = i - start + 1
        if window > best:
            best = window
    return best

