def solve(words, k):
    """Return the k most frequent words.

    Ordered by descending frequency; ties broken alphabetically (ascending).
    If k exceeds the number of distinct words, all distinct words are returned.
    """
    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    ordered = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    return [w for w, _ in ordered[:k]]

